import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.DwAI3uWn.js";const p=JSON.parse('{"title":"Chainy","description":"This repository is the management and documentation hub for Chainy, a 3D Android educational game combining blockchain and AI activities for learners aged 13–17 at Cryptita Pl","frontmatter":{"title":"Chainy","description":"This repository is the management and documentation hub for Chainy, a 3D Android educational game combining blockchain and AI activities for learners aged 13–17 at Cryptita Pl","source":"README.md","category":"Start here","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/readme.md","filePath":"content/readme.md"}'),o={name:"content/readme.md"};function r(s,e,l,c,d,h){return n(),t("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy">Chainy<a class="header-anchor" href="#chainy" aria-label="Link to this section">​</a></h1><p>This repository is the management and documentation hub for Chainy, a 3D Android educational game combining blockchain and AI activities for learners aged 13–17 at Cryptita Plays outreach and mini-library sites. Game source belongs in the separate private <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game repository</a>.</p><p><strong>Pre-final defense: November 21, 2026.</strong> The user reconfirmed zero game implementation progress on October 8. The school requires 60 percent completion, with completed manuscript chapters, functional core modules and pilot-area evidence mandatory. Scoring criterion descriptions and the definition of that percentage remain incomplete. The official September 2026–April 2027 project cycle remains.</p><h2 id="current-decisions">Current decisions<a class="header-anchor" href="#current-decisions" aria-label="Link to this section">​</a></h2><ul><li>Three learning levels: records/ordering; validation/tamper detection; example-based AI classification/output evaluation.</li><li>Free placement and configuration of technology components.</li><li>Required multi-node simulation and AI-agent challenge.</li><li>Offline gameplay with local <strong>SQLite</strong> persistence, superseding the older JSON save design.</li><li>User-confirmed rounded 3D visual style from Chainy storyboard Images 1–2; learning content for ages 13–17; badges and level progress. BlockForge Image 3 supplies gameplay context only.</li><li>English first; retained phone target: Android 10+/11+, 4 GB RAM, 64 GB total device storage, ARM64, OpenGL ES 3.2 or Vulkan 1.1, entry-level-to-midrange GPU. Android 11+ is the provisional test interpretation and Android 10 a compatibility candidate; support remains unmeasured.</li><li>Teacher-issued learner codes identify local profiles; teacher-mediated export supports evaluation without gameplay cloud sync.</li></ul><h2 id="start-here">Start here<a class="header-anchor" href="#start-here" aria-label="Link to this section">​</a></h2><p><strong><a href="/Chainy-Docs/content/docs/documentation-index.html">Full project documentation</a></strong> includes the game design, architecture, schema, hardware plan, evaluation protocol, manuscript draft and individual delegation.</p><p><strong><a href="/Chainy-Docs/content/docs/game-design.html">Illustrated GDD in the requested template</a></strong> includes the supplied visual references, detailed mechanics, numbered game flow and player/UI definitions. Possible beta testing: <strong>November 3–6 at Tambunan National High School, Marinduque</strong>, pending school arrangements and build readiness. The <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">conditional revised forecast</a> brings the beta candidate forward to October 30 and protects readiness checks, fixes, manuscript and rehearsal time. Balanced hour budgets remain estimates because individual availability is unknown.</p><ul><li><a href="/Chainy-Docs/content/docs/documentation-index.html#october-8-coordinated-game-development-package">Coordinated PRD, technical requirements, flow, brief, SQLite schema and GDD</a></li><li><a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">Parallel agent implementation plan</a></li><li><a href="/Chainy-Docs/content/docs/team-delegation.html#october-8-workload-balancing-proposal">Balanced team workload</a></li><li><a href="/Chainy-Docs/content/docs/project-baseline.html">Current baseline and traceable requirements</a></li><li><a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">Pre-final recovery plan</a></li><li><a href="/Chainy-Docs/content/docs/offline-data-plan.html">Offline learning and data collection</a></li><li><a href="/Chainy-Docs/content/docs/mentors.html">Mentor skills and needed human guidance</a></li><li><a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">Official manuscript outline and evidence map</a></li><li><a href="/Chainy-Docs/attachments/docs/backlog.json">Backlog and publication status</a></li><li><a href="/Chainy-Docs/content/docs/archive/kanban-plan-2026-10-05.html">Historical 29-card plan</a></li></ul><p>The current baseline records the user&#39;s latest decisions. Source proposals, classroom reports and the old scope-conflict draft are retained as historical evidence; their age ranges, storage assumptions, status claims and optional features are not automatically current requirements.</p><h2 id="mentor-and-implementation-skills">Mentor and implementation skills<a class="header-anchor" href="#mentor-and-implementation-skills" aria-label="Link to this section">​</a></h2><p>Six project-local mentors challenge feasibility, technical delivery, age appropriateness, blockchain/AI accuracy, offline evidence handling, and defense readiness. Invoke them as listed in <a href="/Chainy-Docs/content/docs/mentors.html">mentors</a>. They advise; they do not replace the capstone adviser or imply appointed human mentors.</p><p>The eight existing implementation skills under <a href="/Chainy-Docs/folders/agents/skills.html">.agents/skills</a> remain available for requirements, architecture, assets/UI, gameplay, performance, QA, release and planning. Read the latest baseline before applying older source documents.</p><h2 id="project-management">Project management<a class="header-anchor" href="#project-management" aria-label="Link to this section">​</a></h2><p>GitHub Projects is selected for the single execution board. Published: <a href="https://github.com/Kamiyon-Studio/Chainy/issues">26 task issues</a> and <a href="https://github.com/Kamiyon-Studio/Chainy/milestones">10 milestones</a>. Existing issue #1 was preserved. The private <a href="https://github.com/orgs/Kamiyon-Studio/projects/5">delivery board</a> has Kanban and table views with status, target date, lead, requirements, blockers and plan IDs. See the backlog for verified publication results. The source repository is <a href="https://github.com/Kamiyon-Studio/Chainy-Game">Chainy-Game</a>.</p></div>',1)])])}const u=a(o,[["render",r]]);export{p as __pageData,u as default};
